{
  "name": "OpenBCI生物电采集板",
  "name_en": "OpenBCI biosensing board",
  "manufacturer": "OpenBCI",
  "description": "这是一种多通道开源生物电信号采集板，主要用于采集脑电信号，并可提供辅助通道输入。设备可通过扩展模块增加通道数，适合用于脑机接口实验、神经信号记录、教学演示以及一般生理电信号采集。",
  "description_en": "This is a multi-channel open-source biosensing board mainly used to acquire EEG signals, with additional auxiliary input channels. It can expand channel count with a daisy module and is commonly used for brain-computer interface experiments, neural signal recording, teaching, and general physiological signal acquisition.",
  "tag_hints": [
    "EEG acquisition",
    "biosignal recording",
    "brain-computer interface",
    "multichannel streaming",
    "daisy expansion",
    "auxiliary channels",
    "60 Hz noise filtering",
    "OpenBCI"
  ],
  "actions": [
    {
      "action_name": "auto-getSampleRate",
      "description": "获取当前采样率。",
      "description_en": "Get the current sampling rate."
    },
    {
      "action_name": "auto-getNbEEGChannels",
      "description": "获取脑电通道数量。",
      "description_en": "Get the number of EEG channels."
    },
    {
      "action_name": "auto-getNbAUXChannels",
      "description": "获取辅助通道数量。",
      "description_en": "Get the number of auxiliary channels."
    },
    {
      "action_name": "auto-run",
      "description": "启动采集板运行流程。",
      "description_en": "Start the board operation flow."
    },
    {
      "action_name": "auto-start_streaming",
      "description": "开始连续输出采样数据流。",
      "description_en": "Start continuous sample data streaming."
    },
    {
      "action_name": "auto-stop",
      "description": "停止数据流采集。",
      "description_en": "Stop data streaming."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与采集板的连接。",
      "description_en": "Disconnect from the board."
    },
    {
      "action_name": "auto-warn",
      "description": "输出设备警告信息。",
      "description_en": "Output a device warning message."
    },
    {
      "action_name": "auto-print_incoming_text",
      "description": "显示设备串口返回的文本信息。",
      "description_en": "Display text returned by the device over the serial connection."
    },
    {
      "action_name": "auto-openbci_id",
      "description": "读取并识别设备ID信息。",
      "description_en": "Read and identify the device ID information."
    },
    {
      "action_name": "auto-print_register_settings",
      "description": "显示寄存器配置设置。",
      "description_en": "Display the register configuration settings."
    },
    {
      "action_name": "auto-print_bytes_in",
      "description": "逐字节显示接收到的输入数据。",
      "description_en": "Display incoming data byte by byte."
    },
    {
      "action_name": "auto-print_packets_in",
      "description": "显示接收到的数据包内容。",
      "description_en": "Display the contents of incoming data packets."
    },
    {
      "action_name": "auto-check_connection",
      "description": "检查连接状态并监测丢包情况。",
      "description_en": "Check connection status and monitor dropped packets."
    },
    {
      "action_name": "auto-reconnect",
      "description": "重新连接采集板。",
      "description_en": "Reconnect the board."
    },
    {
      "action_name": "auto-enable_filters",
      "description": "启用滤波以抑制工频电噪声。",
      "description_en": "Enable filtering to suppress mains electrical noise."
    },
    {
      "action_name": "auto-disable_filters",
      "description": "禁用滤波功能。",
      "description_en": "Disable filtering."
    },
    {
      "action_name": "auto-test_signal",
      "description": "设置或启用测试信号。",
      "description_en": "Set or enable a test signal."
    },
    {
      "action_name": "auto-set_channel",
      "description": "设置指定通道的开关状态。",
      "description_en": "Set the on/off state of a specified channel."
    },
    {
      "action_name": "auto-find_port",
      "description": "查找设备所连接的串口。",
      "description_en": "Find the serial port connected to the device."
    }
  ]
}

